import http from 'node:http';
import { app } from './app.js';
import { pool } from './db.js';

const server = http.createServer(app);
server.keepAliveTimeout = 65_000; // must exceed the load balancer's idle timeout

let ready = true;
let closing = false;

// Readiness is separate from liveness on purpose: this goes unhealthy while
// the process is still perfectly alive and finishing work.
app.get('/ready', (_req, res) => res.status(ready ? 200 : 503).end());

async function shutdown(signal: string) {
  if (closing) return; // a second SIGTERM must not restart the sequence
  closing = true;
  console.info(`${signal}: draining`);

  ready = false;
  // Give the load balancer time to notice before refusing connections.
  await new Promise((r) => setTimeout(r, 5_000).unref());

  const forced = setTimeout(() => {
    console.error('drain timed out, exiting anyway');
    process.exit(1);
  }, 25_000);
  forced.unref();

  await new Promise<void>((resolve) => server.close(() => resolve()));
  await pool.end();
  clearTimeout(forced);
  process.exit(0);
}

for (const signal of ['SIGTERM', 'SIGINT'] as const) {
  process.on(signal, () => void shutdown(signal));
}

server.listen(Number(process.env.PORT ?? 3000));
